      "attribution": "Bản giám định quy thuộc Phạm Khoan (馆藏定本) — Hiện vật trọng yếu tại Bảo tàng Cố Cung Đài Bắc, có chữ ký ẩn của Phạm Khoan trong tán lá được Lý Lâm Xán phát hiện năm 1958.",
