        "debatedIssues": "Cuộc tranh luận về việc liệu mép tranh nguyên thủy có bị cắt xén bớt một phần khi được đóng khung lại dưới triều vua Tống Huy Tông hay không.",
        "comparativeContext": "So sánh với 'Tảo Xuân Đồ' của Quách Hy (chuyển động cuồn cuộn), bức này đạt tới độ bất động vĩnh hằng và uy nghiêm hơn.",
