        "artistBiography": "Trương Trạch Đoan thấu hiểu sâu sắc từ nông thôn ngoại thành, bến thuyền sông Biện đến các ngõ phố sầm uất nội thành, dành nhiều năm tâm huyết hoàn thành tác phẩm hiến dâng Tống Huy Tông.",
        "artisticComposition": "Trải dài hơn 5 mét theo trục ngang với ba đại phân đoạn: 1. Cảnh làng quê ngoại thành thanh bình; 2. Khúc sông Biện tấp nập thuyền bè và cây cầu vồng gỗ Hồng Kiều (虹桥) ngoạn mục; 3. Cổng thành nguy nga dẫn vào khu thương nghiệp buôn bán sầm uất với quán rượu Chính Điếm, tiệm thuốc, lữ quán.",
        "brushwork": "Kỹ thuật Giới họa đỉnh cao: dùng thước kẻ chuẩn xác từng thanh gỗ dầm cầu, cột buồm, mái ngói cong; kết hợp nét vẽ sống động lột tả hơn 814 nhân vật, 28 chiếc thuyền, 60 con vật, 30 ngôi nhà.",
