        "spatialPerspective": "Sử dụng phối cảnh tán điểm (chiếu ngang liên tục di động) tuyệt hảo của hội họa phương Đông: người xem như đang ngồi trên kiệu bay lơ lửng dọc dòng sông và dạo bước qua từng con phố Biện Kinh.",
        "symbolism": "Cảnh tượng một con thuyền lớn sắp va vào gầm cầu Hồng Kiều trong khi đám đông hò reo cứu hộ biểu trưng cho những bất trắc và nguy cơ xã hội đang rình rập đằng sau vẻ ngoài phồn hoa.",
