        "artisticLegacy": "Bức tranh phong tục nổi tiếng nhất trong lịch sử hội họa thế giới, được sao chép hàng trăm phiên bản qua các triều đại Minh, Thanh (như bản Cố Cung Đài Bắc thời Càn Long)."
