        "vi": "Bàn về họa mà cứ đòi hình giống hệt, nhận thức ấy chẳng khác chi con trẻ. Làm thơ mà cứ phải gò bó trong thơ, ắt biết kẻ ấy không phải là thi nhân. Thơ và họa vốn chung một quy luật, cốt ở nét tự nhiên của trời và sự thanh tân.",
