        "artistBiography": "Ngô Trấn cô độc thanh bần suốt đời, không bao giờ xu nịnh quyền quý, tự xưng Mai Hoa Đạo Nhân, lấy hình tượng 'Ngư phụ' (ông chài) làm hóa thân tâm linh của chính mình.",
