        "vi": "Long mạch trong tranh, mở đóng nhấp nhô, trọn vẹn nằm nơi cách dùng bút. Chín thuần mà không ngọt lịm, sống sượng mà kiêm thuần thục, ấy mới đắc được điều huyền diệu mà Thạch Đào không thể với tới.",
