        "brushwork": "Kỹ thuật cọ vẽ đặc sắc hiếm có: dùng bút khô (khát bút) chà xát nhiều lớp, nét bút ngắt quãng nhưng ý tứ liền mạch ('Bút đoạn ý liên'), lớp sau đè lên lớp trước tạo độ đanh chắc như đá hóa thạch.",
        "inkAndColor": "Kỹ thuật 'Sắc trung hữu mặc, mặc trung hữu sắc': pha màu hổ phách, thổ hoàng quyện lẫn mực nho, chưng cất màu sắc thành một thể ánh sáng lung linh trầm ấm.",
