        "vi": "Giang sơn tươi đẹp dường bao, Khiến muôn anh kiệt biết bao cúi đầu. Tiếc Tần Hoàng Hán Vũ, Kém phần văn thải; Đường Tông Tống Tổ, Thiếu nét phong tao. Đều qua cả rồi, Đếm bậc phong lưu, Còn xem hôm nay.",
